function minimumBeautifulSubstrings(s) {
  const beautiful = (t) => {
    if (t[0] === '0') return false;
    let value = 0;
    for (const c of t) value = value * 2 + (c === '1' ? 1 : 0);
    while (value > 1 && value % 5 === 0) value /= 5;
    return value === 1;
  };
  let best = -1;
  const n = s.length;
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    let begin = 0, count = 0, ok = true;
    for (let i = 1; i <= n && ok; i++) {
      if (i === n || (mask >> (i - 1)) & 1) {
        if (!beautiful(s.slice(begin, i))) ok = false;
        count++;
        begin = i;
      }
    }
    if (ok && (best === -1 || count < best)) best = count;
  }
  return best;
}

