function generate(rand, size) {
  const powers = ['1', '101', '11001', '1111101', '1001110001', '110000110101', '11110100001001'];
  const limit = size === 'large' ? 15 : 1 + Math.floor(rand() * 10);
  let s = '';
  if (rand() < 0.25) {
    for (let i = 0; i < limit; i++) s += rand() < 0.6 ? '1' : '0';
    return [s];
  }
  for (let tries = 0; tries < 30; tries++) {
    const piece = powers[Math.floor(rand() * powers.length)];
    if (s.length + piece.length <= limit) s += piece;
  }
  if (s === '') s = '1';
  if (rand() < 0.3) {
    const i = Math.floor(rand() * s.length);
    s = s.slice(0, i) + (s[i] === '1' ? '0' : '1') + s.slice(i + 1);
  }
  return [s];
}
